class Solution {
public:
    vector<vector<int>> subsets(vector<int>& nums) {
        vector<vector<int>> res;
        vector<int> cur;
        function<void(int)> dfs = [&](int idx) {
            if (idx == (int)nums.size()) {
                res.push_back(cur);
                return;
            }
            // Do not take nums[idx]
            dfs(idx + 1);
            // Take nums[idx]
            cur.push_back(nums[idx]);
            dfs(idx + 1);
            cur.pop_back();
        };
        dfs(0);
        return res;
    }
};
